def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    # The compact 3x3 multicolor object is the motif. Stamp it centered on every isolated 1.
    cr,cc=max(pts,key=lambda p:sum(abs(r-p[0])<=1 and abs(c-p[1])<=1 for r,c in pts))
    stamp=[[grid[cr+i-1][cc+j-1] for j in range(3)] for i in range(3)]
    out=[row[:] for row in grid]
    for r,c in pts:
        if grid[r][c]==1 and (abs(r-cr)>1 or abs(c-cc)>1):
            for i in range(3):
                for j in range(3):
                    rr,cc2=r+i-1,c+j-1
                    if 0<=rr<h and 0<=cc2<w:
                        out[rr][cc2]=stamp[i][j]
    return out

